/* ============================================
   Volta Studio — Global Styles
   Minimal, editorial, warm
   ============================================ */

/* ---- Google Fonts ---- */
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,500;0,600;0,700;1,400;1,500&family=Inter:wght@300;400;500;600&display=swap');

/* ---- CSS Variables ---- */
:root {
  --bg: #F5F2ED;
  --bg-warm: #EDE9E3;
  --text: #1A1A1A;
  --text-muted: #6B6560;
  --text-light: #9E9892;
  --accent-terracotta: #C4705A;
  --accent-sage: #8A9A7B;
  --accent-sand: #C4A882;
  --accent-clay: #B85C3D;
  --border: #D9D4CD;
  --font-serif: 'Playfair Display', Georgia, serif;
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --radius: 0.5rem;
  --transition: 200ms ease-out;
}

/* ---- Reset & Base ---- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  font-weight: 400;
  font-size: 16px;
  line-height: 1.65;
  color: var(--text);
  background-color: var(--bg);
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
  transition: opacity var(--transition);
}

a:hover {
  opacity: 0.65;
}

img {
  max-width: 100%;
  display: block;
}

/* ---- Typography ---- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

.text-serif {
  font-family: var(--font-serif);
}

.text-sans {
  font-family: var(--font-sans);
}

/* ---- Layout Utilities ---- */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding-left: 1.5rem;
  padding-right: 1.5rem;
}

@media (min-width: 768px) {
  .container {
    padding-left: 3rem;
    padding-right: 3rem;
  }
}

@media (min-width: 1024px) {
  .container {
    padding-left: 4rem;
    padding-right: 4rem;
  }
}

/* ---- Header ---- */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: rgba(245, 242, 237, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid transparent;
  transition: border-color var(--transition);
}

.site-header.scrolled {
  border-bottom-color: var(--border);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--text);
}

.desktop-nav {
  display: none;
}

.desktop-nav a {
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-weight: 400;
  color: var(--text-muted);
  margin-left: 2rem;
  transition: color var(--transition);
}

.desktop-nav a:hover {
  color: var(--text);
  opacity: 1;
}

.desktop-nav a.active {
  color: var(--text);
}

@media (min-width: 768px) {
  .desktop-nav {
    display: flex;
    align-items: center;
  }
  .menu-toggle {
    display: none;
  }
}

/* ---- Mobile Menu ---- */
.menu-toggle {
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: none;
  border: none;
  cursor: pointer;
  color: var(--text);
  position: relative;
  z-index: 110;
}

.menu-toggle svg {
  width: 24px;
  height: 24px;
  stroke-width: 1.5;
}

.mobile-overlay {
  position: fixed;
  inset: 0;
  z-index: 90;
  background: var(--bg);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 350ms ease-out;
}

.mobile-overlay.open {
  opacity: 1;
  pointer-events: all;
}

.mobile-overlay nav {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
}

.mobile-overlay nav a {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-weight: 500;
  color: var(--text);
  transition: opacity var(--transition);
}

.mobile-overlay nav a:hover {
  opacity: 0.5;
}

/* ---- Hero ---- */
.hero {
  padding-top: 120px;
  padding-bottom: 80px;
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 6vw, 5rem);
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -0.03em;
  max-width: 900px;
}

/* ---- Media Showcase ---- */
.media-showcase {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
  margin-bottom: 100px;
}

@media (min-width: 768px) {
  .media-showcase {
    grid-template-columns: 1fr 1fr 1fr;
    gap: 1.5rem;
  }
}

.media-block {
  aspect-ratio: 4 / 5;
  border-radius: var(--radius);
  overflow: hidden;
}

.media-block.terracotta { background: var(--accent-terracotta); }
.media-block.sage { background: var(--accent-sage); }
.media-block.sand { background: var(--accent-sand); }

/* ---- Client Marquee ---- */
.marquee-section {
  padding-top: 60px;
  padding-bottom: 100px;
  overflow: hidden;
}

.marquee-row {
  display: flex;
  white-space: nowrap;
  will-change: transform;
  padding: 0.75rem 0;
}

.marquee-content {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

.marquee-content span {
  font-family: var(--font-serif);
  font-size: clamp(1.75rem, 4vw, 3rem);
  font-weight: 500;
  color: var(--text);
  padding: 0 1.5rem;
  letter-spacing: -0.01em;
}

.marquee-content .dot {
  color: var(--text-light);
  font-size: 0.6em;
  padding: 0 0.25rem;
  vertical-align: middle;
}

@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

.marquee-row.row-1 .marquee-content {
  animation: marquee-left 35s linear infinite;
}

.marquee-row.row-2 .marquee-content {
  animation: marquee-right 40s linear infinite;
}

.marquee-row.row-3 .marquee-content {
  animation: marquee-left 45s linear infinite;
}

/* ---- About Section ---- */
.about-section {
  padding-top: 80px;
  padding-bottom: 120px;
}

.section-label {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-light);
  margin-bottom: 2rem;
}

.about-text {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 2.5vw, 1.75rem);
  font-weight: 400;
  line-height: 1.55;
  color: var(--text);
  max-width: 800px;
}

.about-text p + p {
  margin-top: 1.5rem;
}

/* ---- Founder Letter ---- */
.letter-section {
  padding-top: 120px;
  padding-bottom: 120px;
}

.letter-container {
  max-width: 680px;
  margin: 0 auto;
}

.letter-heading {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 600;
  margin-bottom: 3rem;
  line-height: 1.15;
}

.letter-body {
  font-family: var(--font-sans);
  font-size: 1.0625rem;
  line-height: 1.8;
  color: var(--text);
}

.letter-body p + p {
  margin-top: 1.75rem;
}

.letter-body strong {
  font-weight: 600;
}

.letter-body em {
  font-style: italic;
  font-family: var(--font-serif);
}

/* ---- Philosophy ---- */
.philosophy-section {
  padding-top: 120px;
  padding-bottom: 80px;
}

.philosophy-heading {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 6vw, 5rem);
  font-weight: 600;
  margin-bottom: 2.5rem;
}

.philosophy-body {
  font-family: var(--font-sans);
  font-size: 1.0625rem;
  line-height: 1.8;
  max-width: 720px;
}

.philosophy-body p + p {
  margin-top: 1.5rem;
}

/* ---- Divider ---- */
.section-divider {
  height: 1px;
  background: var(--border);
  margin: 0 auto;
  max-width: 1280px;
  width: calc(100% - 3rem);
}

@media (min-width: 768px) {
  .section-divider {
    width: calc(100% - 6rem);
  }
}

@media (min-width: 1024px) {
  .section-divider {
    width: calc(100% - 8rem);
  }
}

/* ---- Services ---- */
.services-section {
  padding-top: 100px;
  padding-bottom: 120px;
}

.services-heading {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 600;
  margin-bottom: 4rem;
  max-width: 600px;
}

.service-item + .service-item {
  margin-top: 4rem;
}

.service-item h3 {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 600;
  margin-bottom: 1rem;
}

.service-item p {
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.75;
  color: var(--text-muted);
  max-width: 680px;
}

/* ---- Clients ---- */
.clients-section {
  padding-top: 120px;
  padding-bottom: 120px;
}

.clients-heading {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 600;
  margin-bottom: 1rem;
}

.clients-subheading {
  font-family: var(--font-sans);
  font-size: 1rem;
  color: var(--text-muted);
  margin-bottom: 4rem;
}

.clients-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 3rem;
}

@media (min-width: 640px) {
  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 3rem 2.5rem;
  }
}

@media (min-width: 1024px) {
  .clients-grid {
    grid-template-columns: repeat(3, 1fr);
    gap: 3.5rem 2.5rem;
  }
}

.client-card h3 {
  font-family: var(--font-serif);
  font-size: 1.375rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.client-card p {
  font-family: var(--font-sans);
  font-size: 0.9375rem;
  line-height: 1.65;
  color: var(--text-muted);
}

/* ---- Contact ---- */
.contact-section {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 120px 1.5rem;
}

.contact-heading {
  font-family: var(--font-serif);
  font-size: clamp(4rem, 15vw, 14rem);
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.04em;
  margin-bottom: 3rem;
}

.contact-links {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

@media (min-width: 640px) {
  .contact-links {
    flex-direction: row;
    gap: 2.5rem;
  }
}

.contact-links a {
  font-family: var(--font-sans);
  font-size: 1rem;
  color: var(--text-muted);
  transition: color var(--transition);
}

.contact-links a:hover {
  color: var(--text);
  opacity: 1;
}

/* ---- Footer ---- */
.site-footer {
  padding: 3rem 0;
  border-top: 1px solid var(--border);
  text-align: center;
}

.footer-copy {
  font-family: var(--font-sans);
  font-size: 0.8125rem;
  color: var(--text-light);
}

/* ---- Utility ---- */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ============================================
   Volta Studio — Global Scripts
   ============================================ */

(function () {
  'use strict';

  /* ---- Mobile Menu Toggle ---- */
  const menuToggle = document.getElementById('menuToggle');
  const mobileOverlay = document.getElementById('mobileOverlay');
  const menuOpenIcon = document.getElementById('menuOpenIcon');
  const menuCloseIcon = document.getElementById('menuCloseIcon');

  function toggleMenu() {
    const isOpen = mobileOverlay.classList.toggle('open');
    if (menuOpenIcon) menuOpenIcon.style.display = isOpen ? 'none' : 'block';
    if (menuCloseIcon) menuCloseIcon.style.display = isOpen ? 'block' : 'none';
    document.body.style.overflow = isOpen ? 'hidden' : '';
  }

  if (menuToggle && mobileOverlay) {
    menuToggle.addEventListener('click', toggleMenu);

    // Close menu when clicking a link
    mobileOverlay.querySelectorAll('a').forEach(function (link) {
      link.addEventListener('click', function () {
        toggleMenu();
      });
    });
  }

  /* ---- Header scroll state ---- */
  const header = document.querySelector('.site-header');
  if (header) {
    let ticking = false;
    window.addEventListener('scroll', function () {
      if (!ticking) {
        window.requestAnimationFrame(function () {
          if (window.scrollY > 10) {
            header.classList.add('scrolled');
          } else {
            header.classList.remove('scrolled');
          }
          ticking = false;
        });
        ticking = true;
      }
    });
  }

  /* ---- Marquee: duplicate content for seamless loop ---- */
  document.querySelectorAll('.marquee-row').forEach(function (row) {
    const content = row.querySelector('.marquee-content');
    if (content && !row.dataset.duplicated) {
      const clone = content.cloneNode(true);
      row.appendChild(clone);
      row.dataset.duplicated = 'true';
    }
  });
})();
